using System;
using System.Collections.Generic;
using UnityEngine;

// A Christmas present the Santa Pig (pig_caster_santa) throws out of his sack onto the pigs' side of a battle
// (Resources/Prefabs/0_Generic/4_ChristmasPresents/ChristmasPresent_<Name>). The art is one atlas
// (Resources/ChristmasPresents.png + ChristmasPresentsConfig.json, generated by ArtSource/ChristmasPresents/presents.py):
// each present is a Body, a Lid and a Bow, built here as quads so they can move separately.
//
// The view's own transform is the present's ground point (centre of its base) where it ends up.
//   Toss(from)     flies from a world point (the sack's mouth) to here: pops out of the sack small and stretched, arcs
//                  over spinning end over end, lands tilted with a squash, rocks back onto its base, hops once, its lid
//                  pops and its bow flaps; a few snow puffs/sparkles burst out. The shadow grows on the landing spot.
//   ShowLanded()   just sits here (no flight).
//   Jolt(amount)   the landing reaction at any strength (idle jiggles use it: something rattles inside).
//   PopOut()       shrinks away and destroys the view.
public class ChristmasPresentView : MonoBehaviour
{
	[Serializable]
	private class PartData
	{
		public float[] rect;

		public float[] center;

		public float[] pivot;
	}

	[Serializable]
	private class PresentData
	{
		public string name;

		public float height;

		public float centerY;

		public float footprint;

		public PartData body;

		public PartData lid;

		public PartData bow;
	}

	[Serializable]
	private class PuffData
	{
		public string name;

		public PartData sprite;
	}

	[Serializable]
	private class ConfigData
	{
		public float[] atlasSize;

		public PresentData[] presents;

		public PuffData[] puffs;
	}

	private class Puff
	{
		public Transform Transform;

		public Vector2 Velocity;

		public float Spin;

		public float Age;

		public float Life;

		public float Size;
	}

	public const string ConfigResource = "ChristmasPresentsConfig";

	// Dots, Stripes, Stars, Zigzag, Candy, Snowflake (see ConfigResource).
	public string m_PresentName = "Dots";

	// ChristmasPresents.mat: Unlit/Transparent with the presents atlas.
	public Material m_Material;

	public Texture2D m_ShadowTexture;

	// Shadow width = footprint * x, height = footprint * y.
	public Vector2 m_ShadowScale = new Vector2(1.1f, 0.3f);

	public Vector3 m_ShadowOffset = new Vector3(0f, 3f, 2f);

	[Header("Flight")]
	// Apex of the arc above the higher of the sack and the landing spot.
	public float m_ArcHeight = 170f;

	// Flight time = distance / speed, clamped.
	public float m_FlightSpeed = 650f;

	public float m_MinFlightTime = 0.55f;

	public float m_MaxFlightTime = 1.05f;

	// Pops out of the sack at this size and grows to full size in m_EmergeTime.
	public float m_EmergeScale = 0.4f;

	public float m_EmergeTime = 0.16f;

	// Launch stretch (along y while it is still nearly upright).
	public float m_LaunchStretch = 0.22f;

	// Full turns end over end, in the direction of travel.
	public float m_SpinTurns = 1f;

	// Lands this tilted (degrees, leading edge down) and rocks back onto its base.
	public float m_LandTilt = 16f;

	// How far in front of the landing spot (toward the camera) it flies.
	public float m_FlightZOffset = -30f;

	[Header("Landing")]
	public float m_Squash = 0.26f;

	public float m_SquashFrequency = 22f;

	public float m_SquashDamping = 9f;

	public float m_RockFrequency = 15f;

	public float m_RockDamping = 6.5f;

	public float m_HopHeight = 22f;

	public float m_HopTime = 0.24f;

	public float m_LidPopHeight = 15f;

	public float m_LidPopTime = 0.3f;

	public float m_LidPopTilt = 11f;

	public float m_BowWobble = 20f;

	public int m_PuffCount = 7;

	public float m_PuffSize = 1f;

	public string m_LaunchSoundId = "SkillFX_Generic_BodyAirstream_Small";

	public string m_LandSoundId = "Character_Gen_Bounce_Medium";

	public string m_HopSoundId = "Character_Gen_Bounce_Small";

	[Header("Idle")]
	// Now and then the present jiggles by itself (something rattles inside).
	public bool m_IdleJiggle = true;

	public Vector2 m_IdleJiggleInterval = new Vector2(3.5f, 8f);

	public float m_IdleJiggleStrength = 0.35f;

	public event Action<ChristmasPresentView> Landed;

	private static ConfigData s_Config;

	private readonly List<Mesh> m_Meshes = new List<Mesh>();

	private readonly List<Puff> m_Puffs = new List<Puff>();

	private PresentData m_Data;

	private Material m_ShadowMaterial;

	private Transform m_Mover;

	private Transform m_SquashNode;

	private Transform m_Spin;

	private Transform m_Lid;

	private Transform m_Bow;

	private Transform m_Shadow;

	private Vector3 m_LidRest;

	private Vector3 m_BowRest;

	private Vector3 m_ShadowRest;

	private bool m_Built;

	// Flight
	private bool m_Flying;

	private float m_Delay;

	private float m_FlightTime;

	private float m_FlightDuration;

	private Vector3 m_FromLocal;

	private float m_Apex;

	private float m_Direction;

	private bool m_LaunchSoundPlayed;

	// Reaction to the last landing / jolt
	private bool m_Reacting;

	private float m_ReactTime;

	private float m_ReactStrength;

	private float m_ReactTilt;

	private bool m_HopSoundPlayed;

	private float m_NextJiggle;

	private bool m_PoppingOut;

	private float m_PopOutTime;

	public bool IsFlying => m_Flying;

	public bool HasLanded { get; private set; }

	public float Height => Build() ? m_Data.height : 0f;

	public static string[] PresentNames
	{
		get
		{
			var config = LoadConfig();
			if (config == null)
			{
				return new string[0];
			}
			var names = new string[config.presents.Length];
			for (var i = 0; i < names.Length; i++)
			{
				names[i] = config.presents[i].name;
			}
			return names;
		}
	}

	private static ConfigData LoadConfig()
	{
		if (s_Config == null)
		{
			var text = Resources.Load<TextAsset>(ConfigResource);
			if (text == null)
			{
				Debug.LogError("[ChristmasPresentView] Resources/" + ConfigResource + " not found");
				return null;
			}
			s_Config = JsonUtility.FromJson<ConfigData>(text.text);
		}
		return s_Config;
	}

	private void Awake()
	{
		Build();
	}

	// Builds the quads once; false if the config or the present is missing.
	private bool Build()
	{
		if (m_Built)
		{
			return m_Data != null;
		}
		m_Built = true;
		var config = LoadConfig();
		if (config == null)
		{
			return false;
		}
		foreach (var present in config.presents)
		{
			if (present.name == m_PresentName)
			{
				m_Data = present;
			}
		}
		if (m_Data == null)
		{
			Debug.LogError("[ChristmasPresentView] unknown present '" + m_PresentName + "'");
			return false;
		}
		var atlas = new Vector2(config.atlasSize[0], config.atlasSize[1]);
		m_Shadow = NewNode("Shadow", transform, m_ShadowOffset);
		m_ShadowRest = m_ShadowOffset;
		if (m_ShadowTexture != null)
		{
			m_ShadowMaterial = new Material(m_Material);
			m_ShadowMaterial.mainTexture = m_ShadowTexture;
			var size = new Vector2(m_Data.footprint * m_ShadowScale.x, m_Data.footprint * m_ShadowScale.y);
			AddQuad(m_Shadow, Vector2.zero, size, new Rect(0f, 0f, 1f, 1f), m_ShadowMaterial, "Shadow");
		}
		m_Mover = NewNode("Mover", transform, Vector3.zero);
		m_SquashNode = NewNode("Squash", m_Mover, Vector3.zero);
		m_Spin = NewNode("Spin", m_SquashNode, Vector3.zero);
		// Pieces are laid out around the ground point; nearer pieces get a smaller z (closer to the camera).
		AddPart(m_Spin, "Body", m_Data.body, Vector2.zero, 0f, atlas);
		m_LidRest = new Vector3(m_Data.lid.pivot[0], m_Data.lid.pivot[1], -0.1f);
		m_Lid = NewNode("Lid", m_Spin, m_LidRest);
		AddPart(m_Lid, "Lid", m_Data.lid, Pivot(m_Data.lid), 0f, atlas);
		m_BowRest = new Vector3(m_Data.bow.pivot[0] - m_Data.lid.pivot[0], m_Data.bow.pivot[1] - m_Data.lid.pivot[1], -0.1f);
		m_Bow = NewNode("Bow", m_Lid, m_BowRest);
		AddPart(m_Bow, "Bow", m_Data.bow, Pivot(m_Data.bow), 0f, atlas);
		ScheduleJiggle();
		HasLanded = true;
		return true;
	}

	private static Vector2 Pivot(PartData part)
	{
		return new Vector2(part.pivot[0], part.pivot[1]);
	}

	private Transform NewNode(string name, Transform parent, Vector3 localPosition)
	{
		var node = new GameObject(name).transform;
		node.gameObject.layer = gameObject.layer;
		node.parent = parent;
		node.localPosition = localPosition;
		node.localRotation = Quaternion.identity;
		node.localScale = Vector3.one;
		return node;
	}

	// A quad for an atlas piece, placed so its centre lands on part.center while its parent sits at origin.
	private void AddPart(Transform parent, string name, PartData part, Vector2 origin, float z, Vector2 atlas)
	{
		var center = new Vector2(part.center[0], part.center[1]) - origin;
		var uv = new Rect(part.rect[0] / atlas.x, part.rect[1] / atlas.y, part.rect[2] / atlas.x, part.rect[3] / atlas.y);
		var quad = AddQuad(parent, center, new Vector2(part.rect[2], part.rect[3]), uv, m_Material, name);
		quad.localPosition = new Vector3(quad.localPosition.x, quad.localPosition.y, z);
	}

	private Transform AddQuad(Transform parent, Vector2 center, Vector2 size, Rect uv, Material material, string name)
	{
		var quad = NewNode(name + "Quad", parent, Vector3.zero);
		var half = size * 0.5f;
		var mesh = new Mesh
		{
			name = "ChristmasPresent" + name,
			vertices = new[]
			{
				new Vector3(center.x - half.x, center.y - half.y, 0f), new Vector3(center.x - half.x, center.y + half.y, 0f),
				new Vector3(center.x + half.x, center.y + half.y, 0f), new Vector3(center.x + half.x, center.y - half.y, 0f)
			},
			uv = new[] { new Vector2(uv.xMin, uv.yMin), new Vector2(uv.xMin, uv.yMax), new Vector2(uv.xMax, uv.yMax), new Vector2(uv.xMax, uv.yMin) },
			triangles = new[] { 0, 1, 2, 0, 2, 3 }
		};
		mesh.RecalculateBounds();
		quad.gameObject.AddComponent<MeshFilter>().sharedMesh = mesh;
		quad.gameObject.AddComponent<MeshRenderer>().sharedMaterial = material;
		m_Meshes.Add(mesh);
		return quad;
	}

	// Throws the present from fromWorld (the sack's mouth) to this transform's position, after delay seconds.
	public void Toss(Vector3 fromWorld, float delay = 0f)
	{
		if (!Build())
		{
			return;
		}
		m_FromLocal = transform.InverseTransformPoint(fromWorld);
		var distance = new Vector2(m_FromLocal.x, m_FromLocal.y).magnitude;
		m_FlightDuration = Mathf.Clamp(distance / Mathf.Max(1f, m_FlightSpeed), m_MinFlightTime, m_MaxFlightTime);
		m_Apex = Mathf.Max(m_FromLocal.y, 0f) + m_ArcHeight;
		// Flying toward -x (the pigs face the birds on the left) spins counter-clockwise: top tumbles forward.
		m_Direction = m_FromLocal.x > 0f ? 1f : -1f;
		m_Delay = delay;
		m_FlightTime = 0f;
		m_Flying = true;
		m_Reacting = false;
		m_LaunchSoundPlayed = false;
		HasLanded = false;
		m_Mover.gameObject.SetActive(false);
		m_Shadow.gameObject.SetActive(false);
		ApplyFlight(0f);
	}

	public void ShowLanded()
	{
		if (!Build())
		{
			return;
		}
		m_Flying = false;
		m_Reacting = false;
		HasLanded = true;
		ResetPose();
	}

	// The landing reaction at any strength (1 = a landing).
	public void Jolt(float strength, float tilt = 0f)
	{
		if (!Build() || m_Flying)
		{
			return;
		}
		m_Reacting = true;
		m_ReactTime = 0f;
		m_ReactStrength = strength;
		m_ReactTilt = tilt;
		m_HopSoundPlayed = strength < 0.5f;
	}

	public void PopOut()
	{
		m_PoppingOut = true;
		m_PopOutTime = 0f;
	}

	private void ScheduleJiggle()
	{
		m_NextJiggle = Time.time + UnityEngine.Random.Range(m_IdleJiggleInterval.x, m_IdleJiggleInterval.y);
	}

	private void Update()
	{
		if (m_Data == null)
		{
			return;
		}
		var dt = Time.deltaTime;
		if (m_Flying)
		{
			if (m_Delay > 0f)
			{
				m_Delay -= dt;
				return;
			}
			if (!m_LaunchSoundPlayed)
			{
				m_LaunchSoundPlayed = true;
				m_Mover.gameObject.SetActive(true);
				m_Shadow.gameObject.SetActive(true);
				PlaySound(m_LaunchSoundId);
			}
			m_FlightTime += dt;
			if (m_FlightTime < m_FlightDuration)
			{
				ApplyFlight(m_FlightTime / m_FlightDuration);
			}
			else
			{
				Land();
			}
		}
		else if (m_Reacting)
		{
			m_ReactTime += dt;
			ApplyReaction();
		}
		else if (m_IdleJiggle && !m_PoppingOut && HasLanded && Time.time >= m_NextJiggle)
		{
			Jolt(m_IdleJiggleStrength, UnityEngine.Random.Range(-1f, 1f) * m_LandTilt * 0.3f);
			ScheduleJiggle();
		}
		UpdatePuffs(dt);
		if (m_PoppingOut)
		{
			m_PopOutTime += dt;
			var k = m_PopOutTime / 0.25f;
			// a quick swell, then shrink to nothing
			var s = k < 0.3f ? 1f + 0.15f * k / 0.3f : 1.15f * (1f - (k - 0.3f) / 0.7f);
			m_Mover.localScale = Vector3.one * Mathf.Max(0f, s);
			m_Shadow.localScale = m_Mover.localScale;
			if (k >= 1f)
			{
				Destroy(gameObject);
			}
		}
	}

	private void ApplyFlight(float u)
	{
		// A parabola (constant gravity) through the sack's mouth, the apex and the landing spot.
		var a = m_FromLocal.y;
		var h = m_Apex;
		// y(u) = a(1-u)^2 + 2c u(1-u) with its peak at h: solve the control height c.
		var c = ControlHeight(a, h);
		var y = a * (1f - u) * (1f - u) + 2f * c * u * (1f - u);
		var x = m_FromLocal.x * (1f - u);
		var z = Mathf.Lerp(m_FromLocal.z, 0f, u) + m_FlightZOffset * Mathf.Sin(Mathf.PI * u);
		m_Mover.localPosition = new Vector3(x, y, z);
		var emerge = m_EmergeTime > 0f ? Mathf.Clamp01(m_FlightTime / m_EmergeTime) : 1f;
		var size = Mathf.LerpUnclamped(m_EmergeScale, 1f, EaseOutBack(emerge));
		var stretch = 1f + m_LaunchStretch * (1f - Mathf.Clamp01(m_FlightTime / (m_EmergeTime * 2f)));
		m_SquashNode.localScale = new Vector3(size / Mathf.Sqrt(stretch), size * stretch, 1f);
		// End over end at constant speed, arriving tilted leading edge down.
		var angle = m_Direction * (m_SpinTurns * 360f * (1f - u) + m_LandTilt * u);
		// Spins about its middle, but comes in pivoting on the corner it lands on (where the landing rock pivots).
		var corner = new Vector2(-m_Direction * m_Data.footprint * 0.45f, 0f);
		var toCorner = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.6f, 1f, u));
		SetSpin(angle, Vector2.Lerp(new Vector2(0f, m_Data.centerY), corner, toCorner));
		// The lid lifts a little in the air and the bow flutters.
		m_Lid.localPosition = m_LidRest + new Vector3(0f, 3f * Mathf.Sin(Mathf.PI * u), 0f);
		m_Lid.localRotation = Quaternion.identity;
		m_Bow.localRotation = Quaternion.Euler(0f, 0f, 9f * Mathf.Sin(m_FlightTime * 26f));
		// The shadow grows on the landing spot as the present comes down.
		var shadow = Mathf.Lerp(0.2f, 1f, u * u);
		m_Shadow.localScale = new Vector3(shadow, shadow, 1f);
	}

	// Bezier control height so that the quadratic a(1-u)^2 + 2c u(1-u) (ending at 0) peaks at h (h >= a).
	private static float ControlHeight(float a, float h)
	{
		// Peak value = c^2 / (2c - a) for c > a; solve c^2 - 2hc + ha = 0.
		var disc = Mathf.Max(0f, h * h - h * a);
		return h + Mathf.Sqrt(disc);
	}

	private void Land()
	{
		m_Flying = false;
		HasLanded = true;
		ResetPose();
		PlaySound(m_LandSoundId);
		SpawnPuffs(m_PuffCount);
		Jolt(1f, m_Direction * m_LandTilt);
		ScheduleJiggle();
		if (Landed != null)
		{
			Landed(this);
		}
	}

	private void ResetPose()
	{
		m_Mover.gameObject.SetActive(true);
		m_Shadow.gameObject.SetActive(true);
		m_Mover.localPosition = Vector3.zero;
		m_Mover.localScale = Vector3.one;
		m_SquashNode.localScale = Vector3.one;
		SetSpin(0f, Vector2.zero);
		m_Lid.localPosition = m_LidRest;
		m_Lid.localRotation = Quaternion.identity;
		m_Bow.localPosition = m_BowRest;
		m_Bow.localRotation = Quaternion.identity;
		m_Shadow.localPosition = m_ShadowRest;
		m_Shadow.localScale = Vector3.one;
	}

	private void ApplyReaction()
	{
		var t = m_ReactTime;
		var k = m_ReactStrength;
		// Rocks back from the landing tilt onto its base, pivoting on the low bottom corner.
		var tilt = m_ReactTilt * Mathf.Exp(-m_RockDamping * t) * Mathf.Cos(m_RockFrequency * t);
		var corner = new Vector2(-Mathf.Sign(tilt) * m_Data.footprint * 0.45f, 0f);
		SetSpin(tilt, corner);
		// One hop a moment after impact.
		var hopStart = 0.07f;
		var hopTime = m_HopTime * Mathf.Sqrt(k);
		var hopX = (t - hopStart) / Mathf.Max(0.01f, hopTime);
		var hop = hopX > 0f && hopX < 1f ? m_HopHeight * k * 4f * hopX * (1f - hopX) : 0f;
		m_Mover.localPosition = new Vector3(0f, hop, 0f);
		if (!m_HopSoundPlayed && hopX >= 1f)
		{
			m_HopSoundPlayed = true;
			PlaySound(m_HopSoundId);
		}
		// Squash at impact and again, softer, when the hop comes down.
		var squash = Squash(t, m_Squash * k) + Squash(t - hopStart - hopTime, m_Squash * k * 0.45f);
		m_SquashNode.localScale = new Vector3(1f + squash * 0.9f, 1f - squash, 1f);
		// The lid pops up, tips, and claps back down with a small bounce.
		var lidTime = m_LidPopTime * Mathf.Sqrt(k);
		var lx = t / Mathf.Max(0.01f, lidTime);
		var lid = 0f;
		if (lx < 1f)
		{
			lid = m_LidPopHeight * k * 4f * lx * (1f - lx);
		}
		else if (lx < 1.45f)
		{
			var bx = (lx - 1f) / 0.45f;
			lid = m_LidPopHeight * k * 0.25f * 4f * bx * (1f - bx);
		}
		var lidTilt = lx < 1f ? -Mathf.Sign(m_ReactTilt) * m_LidPopTilt * k * Mathf.Sin(Mathf.PI * lx) : 0f;
		m_Lid.localPosition = m_LidRest + new Vector3(0f, lid, 0f);
		m_Lid.localRotation = Quaternion.Euler(0f, 0f, lidTilt);
		// The bow flaps and settles.
		var bow = m_BowWobble * k * Mathf.Exp(-4f * t) * Mathf.Sin(17f * t);
		m_Bow.localRotation = Quaternion.Euler(0f, 0f, bow);
		m_Bow.localScale = new Vector3(1f + 0.08f * k * Mathf.Exp(-5f * t) * Mathf.Sin(23f * t), 1f, 1f);
		// The shadow tightens while the present is up.
		var sh = 1f - 0.25f * hop / Mathf.Max(1f, m_HopHeight);
		m_Shadow.localScale = new Vector3(sh, sh, 1f);
		if (t > 1.6f)
		{
			m_Reacting = false;
			ResetPose();
		}
	}

	// Damped squash impulse: positive = squashed (shorter, wider).
	private float Squash(float t, float amount)
	{
		if (t < 0f)
		{
			return 0f;
		}
		return amount * Mathf.Exp(-m_SquashDamping * t) * Mathf.Cos(m_SquashFrequency * t);
	}

	// Rotates the art by angle degrees around pivot (in the present's space).
	private void SetSpin(float angle, Vector2 pivot)
	{
		var rotation = Quaternion.Euler(0f, 0f, angle);
		var p = new Vector3(pivot.x, pivot.y, 0f);
		m_Spin.localRotation = rotation;
		m_Spin.localPosition = p - rotation * p;
	}

	private static float EaseOutBack(float x)
	{
		const float c1 = 1.70158f;
		const float c3 = c1 + 1f;
		return 1f + c3 * Mathf.Pow(x - 1f, 3f) + c1 * Mathf.Pow(x - 1f, 2f);
	}

	private void SpawnPuffs(int count)
	{
		var config = LoadConfig();
		if (config == null || config.puffs == null || config.puffs.Length == 0)
		{
			return;
		}
		var atlas = new Vector2(config.atlasSize[0], config.atlasSize[1]);
		for (var i = 0; i < count; i++)
		{
			var data = config.puffs[i % config.puffs.Length];
			var side = (i % 2 == 0) ? -1f : 1f;
			var node = NewNode("Puff", transform, new Vector3(side * UnityEngine.Random.Range(0.2f, 0.5f) * m_Data.footprint, UnityEngine.Random.Range(0f, 8f), -0.5f));
			AddPart(node, data.name, data.sprite, Vector2.zero, 0f, atlas);
			var size = m_PuffSize * UnityEngine.Random.Range(0.55f, 1f) * (data.name == "Sparkle" ? 0.8f : 1f);
			node.localScale = Vector3.one * size;
			m_Puffs.Add(new Puff
			{
				Transform = node,
				Velocity = new Vector2(side * UnityEngine.Random.Range(70f, 170f), UnityEngine.Random.Range(90f, 210f)),
				Spin = UnityEngine.Random.Range(-360f, 360f),
				Life = UnityEngine.Random.Range(0.35f, 0.6f),
				Size = size
			});
		}
	}

	private void UpdatePuffs(float dt)
	{
		for (var i = m_Puffs.Count - 1; i >= 0; i--)
		{
			var puff = m_Puffs[i];
			puff.Age += dt;
			if (puff.Age >= puff.Life || puff.Transform == null)
			{
				if (puff.Transform != null)
				{
					Destroy(puff.Transform.gameObject);
				}
				m_Puffs.RemoveAt(i);
				continue;
			}
			puff.Velocity += new Vector2(-puff.Velocity.x * 3f, -520f) * dt;
			puff.Transform.localPosition += new Vector3(puff.Velocity.x, puff.Velocity.y, 0f) * dt;
			puff.Transform.localRotation = Quaternion.Euler(0f, 0f, puff.Spin * puff.Age);
			var k = puff.Age / puff.Life;
			// pop in, then shrink away
			var s = k < 0.15f ? k / 0.15f : 1f - (k - 0.15f) / 0.85f;
			puff.Transform.localScale = Vector3.one * (puff.Size * Mathf.Max(0f, s));
		}
	}

	private static void PlaySound(string soundId)
	{
		if (string.IsNullOrEmpty(soundId))
		{
			return;
		}
		try
		{
			var audio = DIContainerInfrastructure.AudioManager;
			if (audio != null)
			{
				audio.PlaySound(soundId);
			}
		}
		catch (Exception e)
		{
			// no sound manager outside a booted game (editor previews/probes); the animation goes on regardless
			Debug.LogWarning("[ChristmasPresentView] sound '" + soundId + "': " + e.Message);
		}
	}

	private void OnDestroy()
	{
		if (m_ShadowMaterial != null)
		{
			Destroy(m_ShadowMaterial);
		}
		foreach (var mesh in m_Meshes)
		{
			Destroy(mesh);
		}
	}
}
